{
  "outcome": "escalate",
  "rationale": "This claim is escalated due to a raised fraud flag for an inflated estimate, as the claimed amount is substantially higher than the typical repair cost. Section 7 governs this situation and requires escalation when the amount claimed is substantially higher than usual repair costs. The key fact is the estimate of $20,640.00 is more than double the typical repair cost.",
  "citations": [
    {
      "clause_id": "PREM-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
